from typing import Optional, ClassVar, Dict
from contextlib import contextmanager
from taf.ul.sbts.energy_saving.core.connection_manager import ConnectionManager

try:
    from taf.sbts.oam.coam.admin import admin  # type: ignore
except ModuleNotFoundError:  # pragma: no cover
    admin = None


class EnergySavingContext:
    """Global context for energy saving operations with managers scoped per connection alias."""

    _instances: ClassVar[Dict[str, 'EnergySavingContext']] = {}
    _current_alias: ClassVar[Optional[str]] = None

    def __init__(self, connection_alias: Optional[str]):
        self.connection_alias = connection_alias
        self.admin = admin()
        self.connection_manager = ConnectionManager(connection_alias)

        # Lazy-load managers on first access
        self._delta_manager = None
        self._scf_manager = None
        self._nrcell_manager = None
        self._lncel_manager = None
        self._nrpgrp_manager = None
        self._psgrp_manager = None
        self._parameter_manager = None

    @property
    def delta_manager(self):
        if self._delta_manager is None:
            from taf.ul.sbts.energy_saving.core.delta_manager import DeltaManager
            self._delta_manager = DeltaManager(self)
        return self._delta_manager

    @property
    def scf_manager(self):
        if self._scf_manager is None:
            from taf.ul.sbts.energy_saving.core.scf_manager import SCFManager
            self._scf_manager = SCFManager(self)
        return self._scf_manager

    @property
    def lncel_manager(self):
        if self._lncel_manager is None:
            from taf.ul.sbts.energy_saving.objects.lncel import LNCELManager
            self._lncel_manager = LNCELManager(self)
        return self._lncel_manager

    @property
    def nrcell_manager(self):
        if self._nrcell_manager is None:
            from taf.ul.sbts.energy_saving.objects.nrcell import NRCELLManager
            self._nrcell_manager = NRCELLManager(self)
        return self._nrcell_manager

    @property
    def nrpgrp_manager(self):
        if self._nrpgrp_manager is None:
            from taf.ul.sbts.energy_saving.objects.nrpgrp import NRPGRPManager
            self._nrpgrp_manager = NRPGRPManager(self)
        return self._nrpgrp_manager

    @property
    def psgrp_manager(self):
        if self._psgrp_manager is None:
            from taf.ul.sbts.energy_saving.objects.psgrp import PSGRPManager
            self._psgrp_manager = PSGRPManager(self)
        return self._psgrp_manager

    @property
    def parameter_manager(self):
        if self._parameter_manager is None:
            from taf.ul.sbts.energy_saving.core.parameter_manager import ParameterManager
            self._parameter_manager = ParameterManager(self)
        return self._parameter_manager

    @classmethod
    def initialize(cls, connection_alias: str):
        """Initialize context for a given connection alias and set it as current."""
        if connection_alias not in cls._instances:
            cls._instances[connection_alias] = cls(connection_alias)

        cls._current_alias = connection_alias
        return cls._instances[connection_alias]

    @classmethod
    def get(cls, connection_alias: Optional[str] = None) -> 'EnergySavingContext':
        """Get context - default to current or by provided alias."""
        if connection_alias is None:
            connection_alias = cls._current_alias

        if connection_alias is None:
            raise RuntimeError("No current context set. Call initialize() first.")

        if connection_alias not in cls._instances:
            raise RuntimeError(f"Context for '{connection_alias}' not initialized")

        return cls._instances[connection_alias]

    @classmethod
    def get_or_create(cls, connection_alias: Optional[str]) -> 'EnergySavingContext':
        key = connection_alias or "<unset>"
        ctx = cls._instances.get(key)
        if ctx is None:
            ctx = EnergySavingContext(connection_alias)
            cls._instances[key] = ctx
        return ctx

    @classmethod
    def switch_to(cls, connection_alias: str):
        """Switch current context to a different alias (must already exist)."""
        if connection_alias not in cls._instances:
            raise RuntimeError(f"Context for '{connection_alias}' not found")
        cls._current_alias = connection_alias

    @classmethod
    def list_contexts(cls) -> list:
        """List all available contexts (keys)."""
        return list(cls._instances.keys())

    @classmethod
    def reset(cls, connection_alias: Optional[str] = None):
        """Reset a specific context or all contexts if alias is None."""
        if connection_alias is None:
            cls._instances.clear()
            cls._current_alias = None
        else:
            cls._instances.pop(connection_alias, None)
            if cls._current_alias == connection_alias:
                cls._current_alias = None

    @contextmanager
    def as_current(self):
        """Context manager - temporarily set this context as current."""
        old_current = self.__class__._current_alias
        self.__class__._current_alias = self.connection_alias
        try:
            yield self
        finally:
            self.__class__._current_alias = old_current

    def set_default_connection(self, alias: str):
        """Set default connection alias for this context instance."""
        self.connection_alias = alias
        self.connection_manager.set_default_connection(alias)

    def __repr__(self):
        alias = self.connection_alias if self.connection_alias is not None else "<unset>"
        return f"EnergySavingContext(alias='{alias}')"
